const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const registryPath = path.join(userDataDir, 'trackers_registry.json');
const memoryPath = path.join(userDataDir, 'memory_rules.json');

if (!fs.existsSync(userDataDir)) {
  fs.mkdirSync(userDataDir, { recursive: true });
}

if (!fs.existsSync(registryPath)) {
  fs.writeFileSync(registryPath, JSON.stringify({ trackers: {} }, null, 2), 'utf8');
}

if (!fs.existsSync(memoryPath)) {
  fs.writeFileSync(memoryPath, JSON.stringify({ morning_rules: [], custom_scopes: {} }, null, 2), 'utf8');
}

const now = new Date();
const nowIso = now.toISOString();
const todayIsoDate = nowIso.slice(0, 10);
const nowMs = now.getTime();
const dayMs = 24 * 60 * 60 * 1000;
const cutoff30DaysMs = nowMs - 30 * dayMs;

const inputPayload = $input.first()?.json?.body || $input.first()?.json || {};
const forceCompression = Boolean(inputPayload.force === true || inputPayload.force === 'true');
const minStaleThreshold = forceCompression ? 1 : 5;

// 1. Purge expired volatile rules in memory_rules.json
const memoryRules = JSON.parse(fs.readFileSync(memoryPath, 'utf8'));
let purgedRulesCount = 0;
if (memoryRules.custom_scopes && typeof memoryRules.custom_scopes === 'object') {
  for (const [scopeName, rules] of Object.entries(memoryRules.custom_scopes)) {
    if (Array.isArray(rules)) {
      const filtered = rules.filter((r) => !r.expires_at || r.expires_at >= todayIsoDate);
      const diff = rules.length - filtered.length;
      if (diff > 0) {
        memoryRules.custom_scopes[scopeName] = filtered;
        purgedRulesCount += diff;
      }
    }
  }
}
if (purgedRulesCount > 0) {
  fs.writeFileSync(memoryPath, JSON.stringify(memoryRules, null, 2), 'utf8');
}

// 2. Scan trackers_registry.json and inspect data_<tracker_id>.json
const trackersRegistry = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
const trackers = trackersRegistry.trackers || {};
const candidateItems = [];

const activeCollectionKeywords = ['quote', 'devis', 'pending', 'attente', 'sent', 'envoyé', 'open', 'ouvert', 'active', 'actif', 'in_progress', 'en_cours'];

for (const [trackerId, tracker] of Object.entries(trackers)) {
  const dataFilePath = path.join(userDataDir, `data_${trackerId}.json`);
  if (!fs.existsSync(dataFilePath)) continue;

  let records = [];
  try {
    records = JSON.parse(fs.readFileSync(dataFilePath, 'utf8'));
  } catch (e) {
    records = [];
  }
  if (!Array.isArray(records) || records.length === 0) continue;

  const recentRecords = [];
  const staleRecords = [];

  for (const rec of records) {
    const rawDateStr = rec.updated_at || rec.created_at || rec.date || '';
    const recMs = Date.parse(rawDateStr);
    const isOlderThan30Days = !Number.isNaN(recMs) && recMs < cutoff30DaysMs;

    if (!isOlderThan30Days) {
      recentRecords.push(rec);
      continue;
    }

    // Never archive active/pending COLLECTION_TABLE records (e.g., open CRM quotes/leads)
    if (tracker.type === 'COLLECTION_TABLE') {
      const statusStr = String(rec.status || rec.statut || rec.state || '').toLowerCase().trim();
      const isStillActiveOrPending = !statusStr || activeCollectionKeywords.some((kw) => statusStr.includes(kw));
      if (isStillActiveOrPending) {
        recentRecords.push(rec);
        continue;
      }
    }

    staleRecords.push(rec);
  }

  if (staleRecords.length >= minStaleThreshold) {
    const sortedDates = staleRecords
      .map((r) => String(r.created_at || r.updated_at || r.date || '').slice(0, 10))
      .filter((d) => /^\d{4}-\d{2}-\d{2}$/.test(d))
      .sort();

    const periodStart = sortedDates[0] || todayIsoDate;
    const periodEnd = sortedDates[sortedDates.length - 1] || todayIsoDate;

    candidateItems.push({
      json: {
        needs_compression: true,
        tracker_id: trackerId,
        display_name: tracker.display_name || trackerId,
        tracker_type: tracker.type || 'ACTIVITY_LOG',
        period_start: periodStart,
        period_end: periodEnd,
        stale_count: staleRecords.length,
        stale_records: staleRecords,
        recent_records: recentRecords,
        purged_rules_count: purgedRulesCount,
        timestamp: nowIso
      }
    });
  }
}

if (candidateItems.length === 0) {
  return [
    {
      json: {
        needs_compression: false,
        status: 'ok',
        compressed_trackers: 0,
        purged_rules_count: purgedRulesCount,
        timestamp: nowIso
      }
    }
  ];
}

return candidateItems;

const fs = require('fs');
const path = require('path');

const userDataDir = '/home/node/user_data';
const llmOutputs = $input.all();
const sourceItems = $('Needs Compression?').all();
const nowIso = new Date().toISOString();

const compressedTrackers = [];
let purgedRulesCount = 0;

for (let i = 0; i < sourceItems.length; i++) {
  const src = sourceItems[i].json;
  purgedRulesCount = src.purged_rules_count || 0;
  const rawOutput = String(llmOutputs[i]?.json?.output || '').trim();
  const cleanedJsonStr = rawOutput
    .replace(/^```(?:json)?\s*/i, '')
    .replace(/\s*```$/i, '')
    .trim();

  let digest = {
    period_start: src.period_start,
    period_end: src.period_end,
    record_count: src.stale_count,
    highlights: [`${src.stale_count} entrées archivées automatiquement`],
    summary: cleanedJsonStr || `Compression automatique de ${src.stale_count} entrées historiques pour ${src.display_name}.`
  };

  try {
    const parsed = JSON.parse(cleanedJsonStr);
    if (parsed && typeof parsed === 'object') {
      digest = {
        period_start: parsed.period_start || src.period_start,
        period_end: parsed.period_end || src.period_end,
        record_count: Number(parsed.record_count || src.stale_count),
        highlights: Array.isArray(parsed.highlights) ? parsed.highlights.slice(0, 3) : digest.highlights,
        summary: typeof parsed.summary === 'string' && parsed.summary.trim() ? parsed.summary.trim() : digest.summary
      };
    }
  } catch (e) {
    // Keep fallback digest
  }

  const archivePath = path.join(userDataDir, `archive_${src.tracker_id}.json`);
  let existingArchives = [];
  if (fs.existsSync(archivePath)) {
    try {
      existingArchives = JSON.parse(fs.readFileSync(archivePath, 'utf8'));
      if (!Array.isArray(existingArchives)) existingArchives = [];
    } catch (e) {
      existingArchives = [];
    }
  }

  const archiveEntry = {
    ...digest,
    tracker_id: src.tracker_id,
    archived_at: nowIso
  };
  existingArchives.push(archiveEntry);
  fs.writeFileSync(archivePath, JSON.stringify(existingArchives, null, 2), 'utf8');

  const activeDataPath = path.join(userDataDir, `data_${src.tracker_id}.json`);
  fs.writeFileSync(activeDataPath, JSON.stringify(src.recent_records || [], null, 2), 'utf8');

  compressedTrackers.push({
    tracker_id: src.tracker_id,
    archived_count: src.stale_count,
    remaining_active_count: (src.recent_records || []).length,
    digest: archiveEntry
  });
}

return [
  {
    json: {
      status: 'ok',
      compressed_trackers: compressedTrackers,
      purged_rules_count: purgedRulesCount,
      timestamp: nowIso
    }
  }
];

const first = $input.first()?.json || {};
return [
  {
    json: {
      status: 'ok',
      compressed_trackers: 0,
      purged_rules_count: first.purged_rules_count || 0,
      timestamp: first.timestamp || new Date().toISOString()
    }
  }
];
